    "rubrica": "",
    "testo": "16. (Atto costitutivo e statuto. Modificazioni). L'atto costitutivo e lo statuto devono contenere la denominazione dell'ente, l'indicazione dello scopo, del patrimonio e della sede, nonche' le norme sull'ordinamento e sull'amministrazione. Devono anche determinare, quando trattasi di associazioni, i diritti e gli obblighi degli associati e le condizioni della loro ammissione; e, quando trattasi di fondazioni, i criteri e le modalita' di erogazione delle rendite. L'atto costitutivo e lo statuto possono inoltre contenere le norme relative alla estinzione dell'ente e alla devoluzione del patrimonio, e, per le fondazioni, anche quelle relative alla loro trasformazione."
