    "rubrica": "",
    "testo": "58. (Dichiarazione di morte presunta dell'assente). Quando sono trascorsianni dal giorno a cui risale l'ultima notizia dell'assente, il tribunale competente secondo l'art. 48, su istanza del pubblico ministero o di taluna delle persone indicate nei capoversi dell'art. 50, puo' con sentenza dichiarare presunta la morte dell'assente nel giorno a cui risale l'ultima notizia. In nessun caso la sentenza puo' essere pronunziata se non sono trascorsi nove anni dal raggiungimento della maggiore eta' dell'assente. Puo' essere dichiarata la morte presunta anche se sia mancata la dichiarazione di assenza."
