    "libro": "Libro I — Delle persone e della famiglia",
    "rubrica": "",
    "testo": "89. Divieto temporaneo di nuove nozze. Il tribunale con decreto emesso in camera di consiglio, sentito il pubblico ministero, puo' autorizzare il matrimonio quando e' inequivocabilmente escluso lo stato di gravidanza o se risulta da sentenza passata in giudicato che il marito non ha convissuto con la moglie nei trecento giorni precedenti lo scioglimento, l'annullamento o la cessazione degli effetti civili del matrimonio. Si applicano le disposizioni dei commi quarto, quinto e sesto dell'articolo 84 e del comma quinto dell'articolo 87. Il divieto cessa dal giorno in cui la gravidanza e' terminata."
