    "libro": "Libro II — Delle successioni",
    "rubrica": "",
    "testo": "352. (Dispensa su domanda). Hanno diritto di essere dispensati su loro domanda dall'assumere o dal continuare l'esercizio della tutela: 1) i grandi ufficiali dello Stato non compresi nell'articolo precedente; 2) gli arcivescovi, i vescovi e i ministri del culto aventi cura d'anime; 3); 4) i militari in attivita' di servizio; 5) chi ha compiuto gli anni sessantacinque; 6) chi ha piu' di tre figli minori; 7) chi esercita altra tutela; 8) chi e' impedito di esercitare la tutela da infermita' permanente; 9) chi ha missione dal Governo fuori del Regno o risiede per ragioni di pubblico servizio fuori della circoscrizione del tribunale dove e' costituita la tutela."
