    "testo": "364. (Contenuto dell'inventario). Nell'inventario si indicano gli immobili, i mobili, i crediti e i debiti e si descrivono le carte, note e scritture relative allo stato attivo e passivo del patrimonio, osservando le formalita' stabilite nel."
