    "testo": "388. (Divieto di convenzionidel conto). Nessuna convenzione tra il tutore e il minore divenuto maggiore puo' aver luogodel conto della tutela. La convenzione puo' essere annullata su istanza del minore o dei suoi eredi o aventi causa."
