    "testo": "448-bis (Cessazione per decadenza dell'avente diritto dallasui figli). Il figlio, anche adottivo, e, in sua mancanza, i discendenti prossimi non sono tenuti all'adempimento dell'obbligo di prestare gli alimenti al genitore nei confronti del quale e' stata pronunciata la decadenza dallae, per i fatti che non integrano i casi di indegnita' di cui all'articolo 463, possono escluderlo dalla successione."
