    "rubrica": "",
    "testo": "458. (Divieto di patti successori).e' nulla ogni convenzione con cui taluno dispone della propria successione. E' del pari nullo ogni atto col quale taluno dispone dei diritti che gli possono spettare su una successione non ancora aperta, o rinunzia ai medesimi."
