    "rubrica": "",
    "testo": "480. (Prescrizione). Il diritto di accettare l'eredita' si prescrive in dieci anni. Il termine decorre dal giorno dell'apertura della successione e, in caso d'istituzione condizionale, dal giorno in cui si verifica la condizione.Il termine non corre per i chiamati ulteriori, se vi e' stata accettazione da parte di precedenti chiamati e successivamente il loro acquisto ereditario e' venuto meno."
