    "testo": "493. (Alienazioni dei beni ereditari senza autorizzazione). L'erede decade dal beneficio d'inventario, se aliena o sottopone a pegno o ipoteca beni ereditari, o transige relativamente a questi beni senza l'autorizzazione giudiziaria e senza osservare le forme prescritte dal. Per i beni mobili l'autorizzazione non e' necessaria trascorsi cinque anni dalla dichiarazione di accettare con beneficio d'inventario."
