    "testo": "544. Concorso di ascendentie coniuge. Quando chi muore non lascia, ma ascendentie il coniuge, a quest'ultimo e' riservata la meta' del patrimonio, ed agli ascendenti un quarto.(216) In caso di pluralita' di ascendenti, la quota di riserva ad essi attribuita ai sensi del precedente comma e' ripartita tra i medesimi secondo i criteri previsti dall'articolo 569."
