    "testo": "643. (Amministrazione in caso di eredi nascituri). Le disposizioni dei due precedenti articoli si applicano anche nel caso in cui sia chiamato a succedere un non concepito, figlio di una determinata persona vivente. A questa spetta la rappresentanza del nascituro, per la tutela dei suoi diritti successori, anche quando l'amministratore dell'eredita' e' una persona diversa."
