    "testo": "804. (Termine per l'azione). L'azione di revocazione per sopravvenienza di figli deve essere proposta entro cinque anni dal giorno della nascita dell'ultimo figlioo discendenteovvero della notizia dell'esistenza del figlio o discendente, ovvero dell'avvenuto riconoscimento del figlio. Il donante non puo' proporre o proseguire l'azione dopo la morte del figlio o del discendente."
