    "testo": "1023. (Ambito della famiglia). Nella famiglia si comprendono anche i figli nati dopo che e' cominciato il diritto d'uso o d'abitazione, quantunque nel tempo in cui il diritto e' sorto la persona non avesse contratto matrimonio.Si comprendono infine le persone che convivono con il titolare del diritto per prestare a lui o alla sua famiglia i loro servizi."
