    "libro": "Libro V — Del lavoro",
    "rubrica": "",
    "testo": "1513. (Accertamento dei difetti). In caso di divergenza sulla qualita' o condizione della cosa, il venditore o il compratore possono chiederne la verifica nei modi stabiliti dall'. Il giudice, su istanza della parte interessata, puo' ordinare il deposito o il sequestro della cosa stessa, nonche' la vendita per conto di chi spetta, determinandone le condizioni. La parte che non ha chiesto la verifica della cosa, deve, in caso di contestazione, provarne rigorosamente l'identita' e lo stato."
