    "testo": "1697. (Accertamento della perdita e dell'avaria). Il destinatario ha diritto di fare accertare a sue spese, prima della riconsegna, l'identita' e lo stato delle cose trasportate. Se la perdita o l'avaria esiste, il vettore deve rimborsargli le spese. Salvo diverse disposizioni della legge, la perdita e l'avaria si accertano nei modi stabiliti dall'."
