    "libro": "Libro V — Del lavoro",
    "rubrica": "",
    "testo": "2090. (Procedimento). Il presidente della magistratura del lavoro, ricevuta l'istanza del pubblico ministero, fissa il giorno per la comparizione dell'imprenditore e assegna un termine entro il quale egli deve presentare le sue deduzioni. La magistratura del lavoro decide in camera di consiglio, sentiti il pubblico ministero e l'imprenditore. Puo' anche, prima di decidere, sentire l'associazione professionale alla quale appartiene l'imprenditore, assumere le informazioni e compiere le indagini che ritiene necessarie. Contro la sentenza della magistratura del lavoro l'imprenditore e il pubblico ministero possono proporre ricorso per cassazione a norma dell'."
