    "rubrica": "",
    "testo": "2113. (Rinunzie e transazioni). Le rinunzie e le transazioni, che hanno per oggetto diritti del prestatore di lavoro derivanti da disposizioni inderogabili della legge e dei contratti o accordi collettivi concernenti i rapporti di cui all', non sono valide. L'impugnazione deve essere proposta, a pena di decadenza, entro sei mesi dalla data di cessazione del rapporto o dalla data della rinunzia o della transazione, se queste sono intervenute dopo la cessazione medesima. Le rinunzie e le transazioni di cui ai commi precedenti possono essere impugnate con qualsiasi atto scritto, anche stragiudiziale, del lavoratore idoneo a renderne nota la volonta'. Le disposizioni del presente articolo non si applicano alla conciliazione intervenutadel."
