    "testo": "2142. (Famiglia colonica). La composizione della famiglia colonica non puo' volontariamente essere modificata senza il consenso del concedente, salvi i casi di matrimonio, di adozione e di riconoscimento di. La composizione e le variazioni della famiglia colonica devono risultare dal libretto colonico.(6a)"
