    "rubrica": "",
    "testo": "2233. (Compenso). Il compenso, se non e' convenuto dalle parti e non puo' essere determinato secondo le tariffe o gli usi, e' determinato dal giudice, sentito il parere dell'associazione professionale a cui il professionista appartiene. In ogni caso la misura del compenso deve essere adeguata all'importanza dell'opera e al decoro della professione."
