    "testo": "2257. (Amministrazione disgiuntiva).Se l'amministrazione spetta disgiuntamente a piu' soci, ciascun socio amministratore ha diritto di opporsi all'operazione che un altro voglia compiere, prima che sia compiuta. La maggioranza dei soci, determinata secondo la parte attribuita a ciascun socio negli utili, decide sull'opposizione."
