    "rubrica": "",
    "testo": "2309. (Pubblicazione della nomina dei liquidatori). La deliberazione dei soci o la sentenza che nomina i liquidatori e ogni atto successivo che importa cambiamento nelle persone dei liquidatori devono essere, entrodalla notizia della nomina, depositati in copia autentica a cura dei liquidatori medesimi per l'iscrizione presso l'ufficio del registro delle imprese."
