    "testo": "2409-bis. (Revisione legale dei conti). Lo statuto delle societa' che non siano tenute alla redazione del bilancio consolidato puo' prevedere che la revisione legale dei conti sia esercitata dal collegio sindacale. In tal caso il collegio sindacale e' costituito da revisori legali iscritti nell'apposito registro."
