    "testo": "2669. (Trascrizione anteriore al pagamento dell'imposta di registro). La trascrizione puo' essere domandata, quantunque non sia stata ancora pagata l'imposta di registro a cui e' soggetto il titolo, se si tratta di atto pubblico ricevuto nello Stato o di sentenza pronunziata da un'autorita' giudiziaria dello Stato."
