    "testo": "2683. (Beni per i quali e' disposta la pubblicita'). Devono essere resi pubblici col mezzo della trascrizione, osservate le altre forme di pubblicita' stabilite dalla legge, gli atti menzionati negli articoli seguenti, quando hanno per oggetto: 1) le navi e i galleggianti iscritti nei registri indicati dal; 2) gli aeromobili iscritti nei registri indicati dallo stesso codice; 3) gli autoveicoli iscritti nel pubblico registro automobilistico."
