    "testo": "2691. (Altre domande e atti soggetti a trascrizione). Devono del pari trascriversi, quando si riferiscono ai beni menzionati nell'art. 2683, le domande e gli atti indicati dai numeri 1, 3, 4 e 5 dell'art. 2653, per gli effetti ivi disposti."
