    "testo": "2694. (Richiamo di altre leggi). Sono salve le disposizioni dele delle leggi speciali che richiedono la trascrizione di atti non contemplati dal presente capo e le altre disposizioni non incompatibili con quelle contenute nel capo medesimo."
