    "testo": "2750 (Privilegi marittimi, aeronautici e privilegi stabiliti da leggi speciali). I privilegi sulla nave, sul nolo e sulle cose caricate e i privilegi sull'aeromobile, sul nolo e sulle cose caricate sono regolati dal. Ai privilegi previsti da leggi speciali si applicano le norme di questo capo, se non e' diversamente disposto."
